let metadata=null,pending=null;const images=new Map(),requests=new Map();
export async function hudMetadata(){if(metadata)return metadata;pending??=fetch('assets/realm-hud/atlas-meta-v1.json').then(r=>{if(!r.ok)throw Error('秘境界面信息载入失败');return r.json();}).then(m=>metadata=m).catch(e=>{pending=null;throw e;});return pending;}
async function bitmap(file){if(images.has(file))return images.get(file);if(!requests.has(file))requests.set(file,new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{images.set(file,img);resolve(img);};img.onerror=()=>{requests.delete(file);reject(Error('秘境界面素材载入失败'));};img.src='assets/realm-hud/'+file;}));return requests.get(file);}
export async function ensureHudArt(){await hudMetadata();await Promise.all(['stage-title-plates-v1.png','artifact-pet-controls-v2.png'].map(bitmap));}
export function hudArtwork(f){if(!f||!metadata)return '';const size=metadata.assets[f.file].size;return `<svg class="realm-hud-plate" viewBox="${f.rect.join(' ')}" preserveAspectRatio="none" aria-hidden="true"><image href="assets/realm-hud/${f.file}" width="${size[0]}" height="${size[1]}"/></svg>`;}
export function hudElement(kind,id){return kind==='title'?metadata?.stageTitles.find(f=>f.stageId===id):kind==='artifact'?metadata?.artifactHud.find(f=>f.artifactId===id):metadata?.petEntries.find(f=>f.petId===id||f.petKind===id||f.id===({mossdeer:'deerEntry',emberwing:'griffinEntry',frostfox:'foxEntry'}[id]||id));}
export function hudLayoutStyle(f){if(!f)return '';const [x,y,w,h]=f.rect,s=f.safeRectLocal||[f.safeRect[0]-x,f.safeRect[1]-y,f.safeRect[2],f.safeRect[3]],a=f.avatarCircleLocal;return `--plate-ratio:${w/h};--safe-left:${s[0]/w*100}%;--safe-top:${s[1]/h*100}%;--safe-width:${s[2]/w*100}%;--safe-height:${s[3]/h*100}%;${a?`--avatar-left:${(a[0]-a[2])/w*100}%;--avatar-top:${(a[1]-a[2])/h*100}%;--avatar-size:${a[2]*2/w*100}%;`:''}`;}
export async function loadBossWarningArt(assets){const m=await hudMetadata(),image=await bitmap('boss-warning-rings-v1.png');assets.bossWarnings={image,frames:Object.fromEntries(m.bossWarnings.map(f=>[f.bossId,f]))};}
export function drawBossWarning(c,assets,{bossId,x,y,radius,progress,color='#e3bd7b'}){
 const f=assets.bossWarnings?.frames[bossId],img=assets.bossWarnings?.image;if(!f||!img||!(radius>0))return false;const p=Math.max(0,Math.min(1,progress)),r=f.rect,sx=radius/f.radiusX,ry=radius*.2,sy=ry/f.radiusY,center=f.centerLocal;
 c.save();c.globalAlpha*=.55+.4*p;c.drawImage(img,...r,x-center[0]*sx,y-f.groundContactYLocal*sy,r[2]*sx,r[3]*sy);c.fillStyle='#e39c5020';c.beginPath();c.ellipse(x,y,radius*p,Math.max(.1,ry*p),0,0,Math.PI*2);c.fill();c.strokeStyle='#f7dca4';c.lineWidth=1.2+p;c.beginPath();c.ellipse(x,y,radius,ry,0,-Math.PI/2,-Math.PI/2+Math.PI*2*p);c.stroke();if(p>.75){c.globalAlpha*=Math.min(1,(p-.75)*3);c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.ellipse(x,y,radius*.97,ry*.97,0,0,Math.PI*2);c.stroke();}c.restore();return true;
}
